def faq(n):
    qs=COMUM[:3]+NICHO[n][:4]+COMUM[3:8]+NICHO[n][4:]+COMUM[8:]
    return "".join(f'<div class="avoid" style="margin-bottom:9pt"><h3 style="margin-bottom:3pt">{i+1}. {q}</h3><p style="margin:0">{a}</p></div>' for i,(q,a) in enumerate(qs)), len(qs)
